#!/usr/bin/env python3
"""Reach and selection in every model x question-set cell, in one place (descriptive; for reasoning about mechanism).
For each loop: summary; split by the state of the shared first answer; round-to-round transitions; and, for the critique
loop against a comparison loop, which questions each reaches and what is selected there.
Reads frozen files only. Usage: python3 scripts/mechanism_tables.py
(writes experiments/hle400/t3/mechanism_tables.json and docs/REACH_SELECTION_DATA_TABLES.md)"""
import json,sys,glob
from collections import Counter
from pathlib import Path
sys.path.insert(0,'scripts')
from confirm_common import reco,J,T,toks,ctoks
Q='qwen3.8-flash-payg'; D='deepseek-v4-flash-payg'; M='minimax-m2.5'
C2DS=[d for d in glob.glob('experiments/hle400_C2/*') if Path(d,'loop_trajectories.jsonl').exists()][0]
v3=J('is_correct_t3_sidecar_v3.json')['arms']; rep=J('is_correct_t3_sidecar_rep.json')['arms']; rep3=J('is_correct_t3_sidecar_rep3.json')['arms']; yk=J('is_correct_t3_sidecar_yoke.json')['arms']; ykm=J('is_correct_t3_sidecar_yoke_minimax.json')['arms']
cf=J('is_correct_t3_sidecar_confirm.json')['arms']; cf2=J('is_correct_t3_sidecar_confirm2.json')['arms']; cds=J('is_correct_t3_sidecar_confirm_ds.json')['arms']
CELLS={'deepseek, first 400':{'A2':('experiments/hle400_A2/deepseek-v4-flash',v3['A2']),'A2P':('experiments/hle400_A2PRIME/deepseek-v4-flash-payg',v3['A2P']),'C2':(C2DS,v3['C2']),'A3':('experiments/hle400_A3/deepseek-v4-flash',v3['A3'])},
 'qwen, first 400':{**{a:(f'experiments/rep200_{a}_{Q}/{Q}',rep[a]) for a in ('A2','A2P','C2','A3')},'A2PY':(f'experiments/yoke_A2PY_{Q}/{Q}',yk['A2PY'])},
 'minimax, first 400':{**{a:(f'experiments/rep3_{a}_{M}/{M}',rep3[a]) for a in ('A2','A2P','C2','A3')},'A2PY':(f'experiments/yoke_A2PY_{M}/{M}',ykm['A2PY'])},
 'qwen, new 800':{**{a:(f'experiments/conf_{a}_{Q}/{Q}',cf[a]) for a in ('A2','A2P','A2PY','C2')},'A3':(f'experiments/conf_A3_{Q}/{Q}',cf2['A3'])},
 'deepseek, new 800':{a:(f'experiments/conf_{a}_{D}/{D}',cds[a]) for a in ('A2','A2P','A2PY','C2','A3')}}
NAMES={'A2':'reassuring','A2P':'generic doubt','A2PY':'token-yoked generic doubt','C2':'critique','A3':'nine samples'}
def one(path,side,arm):
    per={}; tr=Counter(); tok=0
    for l in open(path+'/loop_trajectories.jsonl',encoding='utf-8'):
        if not l.strip(): continue
        d=json.loads(l); t=d['task_id']; keys=reco.freeze_keys(d.get('gold_answer',''),d); sl=side[t]; lo,hi=(1,10) if arm=='A3' else (0,len(keys)); ks=keys[lo:hi]
        cnt=Counter(k for k in ks if k is not None); reached=0; sel=0.0
        if cnt:
            ok={k:reco.last_key_correct(keys,sl,k) for k in cnt}; top=max(cnt.values()); tied=[k for k in cnt if cnt[k]==top]; reached=int(any(ok.values())); sel=sum(ok[k] for k in tied)/len(tied)
        state='cut off' if d['rounds'][0].get('finish_reason')=='length' else ('correct' if sl[0]['c'] else 'wrong')
        per[t]=dict(state=state,reached=reached,sel=sel,last=int(bool(sl[hi-1 if hi<=len(sl) else -1]['c'])),cand=len(cnt),rounds=len(ks)); tok+=sum(toks(r)+ctoks(r) for r in d['rounds'][lo:hi])
        if arm!='A3':
            for i in range(len(ks)-1):
                if ks[i] is None or ks[i+1] is None: continue
                a=bool(sl[i]['c']); b=bool(sl[i+1]['c']); same=ks[i+1]==ks[i]; tr['C' if a else 'W']+=1
                if a: tr['C_kept' if (same or b) else 'C_to_wrong']+=1
                else: tr['W_kept' if same else ('W_to_correct' if b else 'W_to_other')]+=1
    return per,tr,tok
OUT={}; MD=['# Reach and selection: all cells (generated by scripts/mechanism_tables.py; descriptive)','','Definitions as in the paper. *Reached*: a correct answer appears among the answers. *Selected*: the most frequent answer is correct. The first answer (T=0) is shared by all loops of a cell. Independent samples: samples 1-9. Tokens: millions, solver and critic.','']
for cell,arms in CELLS.items():
    P={}; O={'loops':{}}; n=None
    for arm,(path,side) in arms.items():
        per,tr,tok=one(path,side,arm); P[arm]=per; n=len(per); S=lambda key,f=None: sum(v[key] for v in per.values() if f is None or v['state'] in f)
        w=('wrong','cut off'); nw=sum(v['state'] in w for v in per.values()); nc=n-nw
        O['loops'][NAMES[arm]]={'reached':S('reached'),'selected':round(S('sel'),1),'last':S('last') if arm!='A3' else None,'selected_per_reached':round(S('sel')/max(1,S('reached')),3),'tokens_M':round(tok/1e6,1),'rounds_per_q':round(S('rounds')/n,2),'candidates_per_q':round(S('cand')/n,2),
          'first_correct':{'n':nc,'still_selected':round(S('sel',('correct',)),1),'lost':round(nc-S('sel',('correct',)),1)},
          'first_wrong_or_cut_off':{'n':nw,'cut_off':sum(v['state']=='cut off' for v in per.values()),'reached':S('reached',w),'selected':round(S('sel',w),1),'selected_per_reached':round(S('sel',w)/max(1,S('reached',w)),3)},
          'transitions':None if arm=='A3' else {'after_correct_kept':round(tr['C_kept']/max(1,tr['C']),3),'after_incorrect_kept':round(tr['W_kept']/max(1,tr['W']),3),'after_incorrect_to_correct':round(tr['W_to_correct']/max(1,tr['W']),3),'after_incorrect_to_other_incorrect':round(tr['W_to_other']/max(1,tr['W']),3)}}
    O['n']=n; O['first_answer_correct']=sum(v['state']=='correct' for v in P['C2'].values()); O['composition']={}
    for other in ('A2','A2PY','A3'):
        if other not in P: continue
        ts=[t for t in P['C2'] if P['C2'][t]['state']!='correct']; g={'reached by both':[t for t in ts if P['C2'][t]['reached'] and P[other][t]['reached']],'reached only by critique':[t for t in ts if P['C2'][t]['reached'] and not P[other][t]['reached']],f'reached only by {NAMES[other]}':[t for t in ts if P[other][t]['reached'] and not P['C2'][t]['reached']]}
        fc=[t for t in P['C2'] if P['C2'][t]['state']=='correct']
        O['composition'][NAMES[other]]={**{k:{'n':len(v),'selected_other':round(sum(P[other][t]['sel'] for t in v),1),'selected_critique':round(sum(P['C2'][t]['sel'] for t in v),1)} for k,v in g.items()},'first answer correct':{'n':len(fc),'selected_other':round(sum(P[other][t]['sel'] for t in fc),1),'selected_critique':round(sum(P['C2'][t]['sel'] for t in fc),1)}}
    OUT[cell]=O; L=O['loops']
    MD+=[f"## {cell} ({n} questions; first answer correct on {O['first_answer_correct']})",'','| Loop | Reached | Selected | Last | Sel./reached | Tokens | Rounds/q | Candidates/q |','|---|---|---|---|---|---|---|---|']
    MD+=[f"| {k} | {v['reached']} | {v['selected']} | {v['last'] if v['last'] is not None else '-'} | {v['selected_per_reached']:.2f} | {v['tokens_M']} | {v['rounds_per_q']} | {v['candidates_per_q']} |" for k,v in L.items()]
    MD+=['','By state of the first answer:','','| Loop | First correct: n | lost | First wrong or cut off: n | reached | selected | sel./reached |','|---|---|---|---|---|---|---|']
    MD+=[f"| {k} | {v['first_correct']['n']} | {v['first_correct']['lost']} | {v['first_wrong_or_cut_off']['n']} | {v['first_wrong_or_cut_off']['reached']} | {v['first_wrong_or_cut_off']['selected']} | {v['first_wrong_or_cut_off']['selected_per_reached']:.2f} |" for k,v in L.items()]
    MD+=['','Round-to-round transitions:','','| Loop | After a correct answer: kept | After an incorrect answer: kept | changed to correct | changed to another incorrect |','|---|---|---|---|---|']
    MD+=[f"| {k} | {v['transitions']['after_correct_kept']:.2f} | {v['transitions']['after_incorrect_kept']:.2f} | {v['transitions']['after_incorrect_to_correct']:.3f} | {v['transitions']['after_incorrect_to_other_incorrect']:.2f} |" for k,v in L.items() if v['transitions']]
    for other,c in O['composition'].items():
        MD+=['',f"Critique loop against {other}, by which loop reaches the question (selected: {other} / critique):",'','| Questions | n | Selected, '+other+' | Selected, critique | Difference |','|---|---|---|---|---|']
        MD+=[f"| {k} | {v['n']} | {v['selected_other']} | {v['selected_critique']} | {v['selected_critique']-v['selected_other']:+.1f} |" for k,v in c.items()]
    MD.append('')
    print(cell,'done')
json.dump(OUT,open(T+'mechanism_tables.json','w'),indent=1); open('docs/REACH_SELECTION_DATA_TABLES.md','w').write('\n'.join(MD)+'\n')
